function open(kind,key=null){if(kind==='print'&&(!data.products.length||!data.spools.length))return alert('Add a product and a filament type first.');if(kind==='sale'&&!data.products.length)return alert('Add a product first.');if(kind==='sale'&&!data.spools.length)return alert('Add a filament colour first.');if(kind==='product'){photoDraft=photoSrc(product(key));photoBusy=false}modal=kind;editId=key;render()}
function allocate(pid,quantity){let remain=quantity,total=0;const batches=unsoldCosts(pid);for(const b of batches){const take=Math.min(b.q,remain);total+=take*b.cost;remain-=take;if(remain<=0)break;}return {cost:total,shortfall:remain}}
function submit(form){const f=Object.fromEntries(new FormData(form));let msg='';
if(modal==='purchase'){const amount=Number(f.amount),rolls=f.rolls===''?null:Number(f.rolls);if(!Number.isFinite(amount)||amount<=0)return alert('Enter the total amount paid.');if(rolls!==null&&(!Number.isInteger(rolls)||rolls<1))return alert('Roll count must be a whole number.');const item={id:editId||id(),amount:Math.round(amount*100)/100,date:f.date||today(),rolls,note:(f.note||'').trim()};if(editId)data.purchases=data.purchases.map(p=>p.id===editId?item:p);else data.purchases.push(item)}
if(modal==='product'){if(photoBusy)return alert('Please wait for the photo to finish processing.');const item={id:editId||id(),name:f.name.trim(),variant:'',multicolour:f.printMode==='multi',filamentId:f.filamentId,price:n(f.price),grams:n(f.grams),hours:n(f.hours),notes:f.notes,photo:photoDraft};if(editId)data.products=data.products.map(p=>p.id===editId?item:p);else data.products.push(item)}
if(modal==='spool'){const brand=f.brand==='Other'?f.customBrand.trim():f.brand;if(!brand)return alert('Enter a brand name.');if(!f.colorName.trim())return alert('Enter a colour name.');if(n(f.grams)<=0)return alert('Roll size must be greater than zero.');const item={id:editId||id(),brand,material:f.material,color:f.color,colorName:f.colorName.trim(),price:n(f.price),grams:n(f.grams),purchasePrices:editId?[...rollPrices(spool(editId))]:[n(f.price)]};if(editId)data.spools=data.spools.map(s=>s.id===editId?item:s);else data.spools.push(item)}
if(modal==='print'){const q=n(f.quantity),good=n(f.good),grams=n(f.grams),s=spool(f.spoolId);if(!s)return alert('Select a filament type');if(!Number.isInteger(q)||!Number.isInteger(good)||good>q)return alert('Successful quantity must be a whole number no greater than attempted quantity.');const mc=grams*costSpool(s),ec=n(f.hours)*n(data.settings.power)/1000*n(data.settings.rate),wc=n(f.hours)*n(data.settings.wear),oc=n(f.otherCost);const failedRatio=q?Math.max(0,q-good)/q:0;const item={id:id(),productId:f.productId,spoolId:s.id,filamentLabel:s.brand+' '+s.material+' '+s.colorName,filamentRollPrice:n(s.price),filamentRollGrams:n(s.grams),date:f.date,quantity:q,good,grams,hours:n(f.hours),materialCost:mc,energyCost:ec,wearCost:wc,otherCost:oc,failedCost:(mc+ec+wc+oc)*failedRatio};data.prints.push(item)}

if(modal==='sale'){const q=n(f.quantity);if(!Number.isInteger(q)||q<1)return alert('Quantity must be a whole number greater than zero.');const p=product(f.productId);if(!p)return alert('Choose a product.');let filaments;try{filaments=isMulti(p)?readMulti(form):null}catch(err){return alert(err.message)}const s=isMulti(p)?spool(filaments[0].spoolId):spool(f.spoolId);if(!s)return alert('Choose a filament colour.');const grams=isMulti(p)?filaments.reduce((sum,x)=>sum+x.grams,0):(f.grams===''?n(p.grams):n(f.grams??p.grams)),hours=f.hours===''?n(p.hours):n(f.hours??p.hours);const mat=q*(isMulti(p)?multiCost(filaments):grams*costSpool(s)),extra=q*(hours*n(data.settings.power)/1000*n(data.settings.rate)+hours*n(data.settings.wear)+n(data.settings.packaging));const item={id:(data.sales.some(z=>z.id===editId)?editId:id()),productId:p.id,productName:p.name,spoolId:s.id,colorName:isMulti(p)?filaments.map(x=>x.colorName).join(' / '):s.colorName,colorSnapshot:s.color,filaments:isMulti(p)?filaments:undefined,grams,hours,date:f.date||today(),quantity:q,price:n(f.price),discount:n(f.discount),postage:n(f.postage),shipping:n(f.shipping),fees:n(f.fees),materialCost:mat,otherCost:extra,cogs:mat+extra,channel:'Sale',notes:f.notes||''};if(data.sales.some(z=>z.id===editId))data.sales=data.sales.map(z=>z.id===editId?item:z);else data.sales.push(item)}

if(modal==='expense')data.expenses.push({id:id(),date:f.date,name:f.name,amount:n(f.amount)});
if(modal==='settings'){const goalEnabled=f.goalEnabled==='on',goalName=String(f.goalName||'').trim(),goalAmount=Number(f.goalAmount);if(goalEnabled&&(!goalName||!Number.isFinite(goalAmount)||goalAmount<=0))return alert('Enter a goal name and a target greater than $0.');data.settings={...data.settings,printer:f.printer,power:n(f.power),rate:n(f.rate),wear:n(f.wear),packaging:n(f.packaging),goalEnabled,goalName,goalAmount:Number.isFinite(goalAmount)&&goalAmount>0?goalAmount:0}}
modal=null;editId=null;save()}
function download(name,mime,text){const link=document.createElement('a'),blob=new Blob([text],{type:mime});link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500)}
function exportCSV(){const cols=['date','product','quantity','unitPrice','discount','postageCharged','shippingCost','fees','productionCOGS','revenue','profit','channel'];const rows=data.sales.map(s=>[s.date,product(s.productId)?.name||'',s.quantity,s.price,s.discount,s.postage,s.shipping,s.fees,s.cogs,n(s.price)*n(s.quantity)-n(s.discount)+n(s.postage),n(s.price)*n(s.quantity)-n(s.discount)+n(s.postage)-n(s.shipping)-n(s.fees)-n(s.cogs),s.channel]);const csv=[cols,...rows].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');download('print-ledger-sales.csv','text/csv',csv)}
let lastDeleted=null;
function removeEntry(type,key){let bucket=type==='product'?'products':type==='filament'?'spools':type==='purchase'?'purchases':'sales';const item=data[bucket].find(v=>v.id===key);if(!item)return;if(!confirm('Delete this '+type+'? You can undo it immediately afterward.'))return;data[bucket]=data[bucket].filter(v=>v.id!==key);lastDeleted={bucket,item};modal=null;editId=null;save();showUndo()}
function showUndo(){let old=document.querySelector('.undo-toast');old?.remove();const el=document.createElement('div');el.className='undo-toast';el.innerHTML='Entry deleted <button id="undoDeletion">Undo</button>';document.body.append(el)}
function quickSale(pid){const p=product(pid);if(!p)return; if(!data.spools.length)return alert('Add a filament colour first.');modal='quick-colour';editId=pid;render()}
function confirmQuickSale(sid){const p=product(editId),s=spool(sid);if(!p||!s)return alert('Please select a filament colour.');const mat=n(p.grams)*costSpool(s),extra=n(p.hours)*n(data.settings.power)/1000*n(data.settings.rate)+n(p.hours)*n(data.settings.wear)+n(data.settings.packaging);data.sales.push({id:id(),productId:p.id,productName:p.name,spoolId:s.id,colorName:s.colorName,colorSnapshot:s.color,date:today(),quantity:1,price:n(p.price),grams:n(p.grams),hours:n(p.hours),materialCost:mat,otherCost:extra,cogs:mat+extra,discount:0,postage:0,shipping:0,fees:0,channel:'Sale',notes:''});modal=null;editId=null;save();const el=document.createElement('div');el.className='undo-toast';el.textContent='Sold one '+p.name+' in '+s.colorName+' · '+money(n(p.price)-mat-extra)+' estimated profit';document.body.append(el);setTimeout(()=>el.remove(),4500)}
function confirmQuickMulti(){const p=product(editId);if(!p)return;let filaments;try{filaments=readMulti($('#quickMultiForm'))}catch(err){return alert(err.message)}const grams=filaments.reduce((sum,f)=>sum+f.grams,0),mat=multiCost(filaments),extra=n(p.hours)*n(data.settings.power)/1000*n(data.settings.rate)+n(p.hours)*n(data.settings.wear)+n(data.settings.packaging);const s=spool(filaments[0].spoolId);data.sales.push({id:id(),productId:p.id,productName:p.name,spoolId:s.id,colorName:filaments.map(f=>f.colorName).join(' / '),colorSnapshot:s.color,filaments,date:today(),quantity:1,price:n(p.price),grams,hours:n(p.hours),materialCost:mat,otherCost:extra,cogs:mat+extra,discount:0,postage:0,shipping:0,fees:0,channel:'Sale',notes:''});modal=null;editId=null;save();const el=document.createElement('div');el.className='undo-toast';el.textContent='Sold one '+p.name+' · '+money(n(p.price)-mat-extra)+' estimated profit';document.body.append(el);setTimeout(()=>el.remove(),4500)}
function updateQuickMultiPreview(){const el=$('#quickMultiPreview'),p=product(editId);if(!el||!p)return;let material=0,grams=0;for(const row of document.querySelectorAll('#quickMultiForm .multi-row')){const s=spool(row.querySelector('.multi-filament').value),g=n(row.querySelector('.multi-grams').value);material+=g*costSpool(s);grams+=g}const extra=n(p.hours)*n(data.settings.power)/1000*n(data.settings.rate)+n(p.hours)*n(data.settings.wear)+n(data.settings.packaging);el.innerHTML='<div><span>Total filament</span><strong>'+Math.round(grams*10)/10+' g</strong></div><div><span>Material cost</span><strong>−'+money(material)+'</strong></div><div><span>Other estimated costs</span><strong>−'+money(extra)+'</strong></div><div class="preview-profit"><span>Estimated profit</span><strong>'+money(n(p.price)-material-extra)+'</strong></div>'}
function updateModeVisibility(){const multi=$('#f_printMode')?.value==='multi';for(const name of ['grams','filamentId']){const field=$('#f_'+name)?.closest('.field');if(field)field.style.display=multi?'none':''}}

function updateSalePreview(){if(modal!=='sale')return;const el=$('#saleCostPreview');if(!el)return;const p=product($('#f_productId')?.value),s=spool($('#f_spoolId')?.value),q=n($('#f_quantity')?.value||1),price=n($('#f_price')?.value),grams=n($('#f_grams')?.value??p?.grams),hours=n($('#f_hours')?.value??p?.hours);let mat=q*grams*costSpool(s);if(isMulti(p)){mat=q*[...document.querySelectorAll('#saleFilamentArea .multi-row')].reduce((total,row)=>total+n(row.querySelector('.multi-grams').value)*costSpool(spool(row.querySelector('.multi-filament').value)),0)}const extra=q*(hours*n(data.settings.power)/1000*n(data.settings.rate)+hours*n(data.settings.wear)+n(data.settings.packaging));const total=q*price-n($('#f_discount')?.value)+n($('#f_postage')?.value)-n($('#f_shipping')?.value)-n($('#f_fees')?.value);el.innerHTML='<div><span>Sale total</span><strong>'+money(total)+'</strong></div><div><span>Material cost</span><strong>−'+money(mat)+'</strong></div><div><span>Other estimated costs</span><strong>−'+money(extra)+'</strong></div><div class="preview-profit"><span>Estimated profit</span><strong>'+money(total-mat-extra)+'</strong></div>'}
document.addEventListener('click',e=>{if(e.target.id==='undoDeletion'&&lastDeleted){data[lastDeleted.bucket].push(lastDeleted.item);lastDeleted=null;document.querySelector('.undo-toast')?.remove();save();return}if(e.target.id==='advancedToggle'){document.querySelector('#advancedFields')?.classList.toggle('collapsed');return}const b=e.target.closest('[data-page],[data-act]');if(b?.dataset.act==='add-multi'){const container=b.closest('.multi-editor').querySelector('.multi-rows');container.insertAdjacentHTML('beforeend',multiRows([{spoolId:data.spools[0]?.id,grams:''}]));updateQuickMultiPreview();updateSalePreview();return}if(b?.dataset.act==='remove-multi'){const rows=b.closest('.multi-rows');if(rows.querySelectorAll('.multi-row').length>1)b.closest('.multi-row').remove();updateQuickMultiPreview();updateSalePreview();return}if(b?.dataset.page){page=b.dataset.page;modal=null;render();window.scrollTo(0,0);return}if(b?.dataset.act){const act=b.dataset.act;if(act==='close'){modal=null;render()}else if(act.startsWith('roll-plus:')){adjustRolls(act.slice(10),1)}else if(act.startsWith('roll-minus:')){adjustRolls(act.slice(11),-1)}else if(act.startsWith('quick:')){quickSale(act.split(':')[1])}else if(act.startsWith('confirm-colour:')){confirmQuickSale(act.slice('confirm-colour:'.length))}else if(act.startsWith('delete-')){const [kind,key]=act.split(':');removeEntry(kind.slice(7),key)}else if(act==='export')download('print-ledger-backup-'+today()+'.json','application/json',JSON.stringify(data,null,2));else if(act==='csv')exportCSV();else{const [kind,key]=act.split(':');open(kind==='sell'||kind==='edit-sale'?'sale':kind,key||null)}return}if(e.target.id==='undoDeletion'&&lastDeleted){data[lastDeleted.bucket].push(lastDeleted.item);lastDeleted=null;document.querySelector('.undo-toast')?.remove();save();return}if(e.target.id==='advancedToggle'){document.querySelector('#advancedFields')?.classList.toggle('collapsed');return}if(e.target.classList.contains('dialog-back')){modal=null;render()}});
document.addEventListener('click',e=>{const action=e.target.closest('[data-act]')?.dataset.act;if(action==='remove-photo'){e.preventDefault();e.stopImmediatePropagation();photoDraft='';refreshPhotoPreview()}else if(action?.startsWith('preview-photo:')){e.preventDefault();e.stopImmediatePropagation();modal='photo-preview';editId=action.slice('preview-photo:'.length);render()}},true);
document.addEventListener('change',async e=>{if(e.target.id!=='productPhotoFile')return;const file=e.target.files?.[0];if(!file)return;const editing=editId;photoBusy=true;try{const result=await compressPhoto(file);if(modal==='product'&&editId===editing){photoDraft=result;refreshPhotoPreview()}}catch(err){alert(err.message)}finally{photoBusy=false}});
document.addEventListener('input',e=>{if(modal==='sale')updateSalePreview();if(modal==='quick-colour')updateQuickMultiPreview()});
document.addEventListener('submit',e=>{if(e.target.id==='editor'){e.preventDefault();submit(e.target)}if(e.target.id==='quickMultiForm'){e.preventDefault();confirmQuickMulti()}});
document.addEventListener('change',async e=>{if(e.target.id==='importFile'){const file=e.target.files?.[0];if(!file)return;try{const incoming=JSON.parse(await file.text());if(!['products','spools','prints','sales'].every(k=>Array.isArray(incoming[k])))throw Error('Invalid backup');if(!confirm('This will replace all existing local records. Continue?'))return;data={...blank(),...incoming};modal=null;save()}catch(err){alert('Cannot import backup: '+err.message)}}if(e.target.id==='f_productId'){const p=product(e.target.value);if(p&&modal==='sale'){$('#f_price').value=p.price;const area=$('#saleFilamentArea');if(area)area.innerHTML=isMulti(p)?multiEditor([{spoolId:data.spools[0]?.id,grams:''},{spoolId:data.spools[1]?.id||data.spools[0]?.id,grams:''}]):select('spoolId','Printed colour',data.spools.map(s=>[s.id,s.colorName+' · '+s.brand+' '+s.material]),p.filamentId||data.spools[0]?.id);if($('#f_grams'))$('#f_grams').value=p.grams;if($('#f_hours'))$('#f_hours').value=p.hours;updateSalePreview()}if(p&&modal==='print'){$('#f_grams').value=p.grams;$('#f_hours').value=p.hours;updateFilamentEstimate()}}});

function updateFilamentEstimate(){if(modal!=='print')return;const el=$('#filamentEstimate'),s=spool($('#f_spoolId')?.value);if(el&&s)el.textContent='Estimated filament cost: '+money(n($('#f_grams')?.value)*costSpool(s))+' for '+n($('#f_grams')?.value)+' g. This exact cost is recorded when the print is saved.'}
document.addEventListener('input',e=>{if(['f_grams','f_spoolId'].includes(e.target.id))updateFilamentEstimate()});
document.addEventListener('change',e=>{if(e.target.id==='salesSort'){saleSort=e.target.value;render();return}if(e.target.id==='f_goalEnabled')updateGoalVisibility();if(e.target.id==='f_spoolId')updateFilamentEstimate();if(e.target.id==='f_printMode')updateModeVisibility();if(modal==='sale')updateSalePreview();if(modal==='quick-colour')updateQuickMultiPreview()});
render();
